import{_ as t,a,c as n,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第四册：流利英语 · Lesson 36 The cost of government","description":"学习 倍数比较与百分比基数，配有原创例句、重点词汇和带解析的自测。","frontmatter":{"title":"第四册：流利英语 · Lesson 36 The cost of government","description":"学习 倍数比较与百分比基数，配有原创例句、重点词汇和带解析的自测。","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"路线与能力起点","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"新概念英语经典版第4册课时","summary":"学习 倍数比较与百分比基数，配有原创例句、重点词汇和带解析的自测。","status":"active","related":[{"title":"程序员英语 08：一次完整的阅读与协作实战","link":"/life/english/programmer/practice","kind":"读写与对话练习","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语","link":"/life/english/new-concept/book-2/unit-01/vocabulary","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 第17–24课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-02","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 单词与短语 · 字母索引与第1–16课","link":"/life/english/new-concept/book-2/unit-01/vocabulary-part-01","kind":"句法与表达查阅","scope":"general","audience":"general"},{"title":"第二册：实践与进步 · 单元 1 复习与自测","link":"/life/english/new-concept/book-2/unit-01/review","kind":"读写与对话练习","scope":"general","audience":"general"}],"prev":{"text":"第四册：流利英语 · Lesson 35 Space odyssey","link":"/life/english/new-concept/book-4/unit-05/lesson-035"},"next":{"text":"第四册：流利英语 · Lesson 37 The process of ageing","link":"/life/english/new-concept/book-4/unit-05/lesson-037"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第四册：流利英语 · Lesson 35 Space odyssey","link":"/life/english/new-concept/book-4/unit-05/lesson-035"},"next":{"text":"第四册：流利英语 · Lesson 37 The process of ageing","link":"/life/english/new-concept/book-4/unit-05/lesson-037"}},"headers":[],"relativePath":"life/english/new-concept/book-4/unit-05/lesson-036.md","filePath":"life/english/new-concept/book-4/unit-05/lesson-036.md"}'),i={name:"life/english/new-concept/book-4/unit-05/lesson-036.md"};function s(r,e,l,c,h,d){return a(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="第四册-流利英语-·-lesson-36-the-cost-of-government" tabindex="-1">第四册：流利英语 · Lesson 36 The cost of government <a class="header-anchor" href="#第四册-流利英语-·-lesson-36-the-cost-of-government" aria-label="Permalink to &quot;第四册：流利英语 · Lesson 36 The cost of government&quot;">​</a></h1><p><a href="/life/english/new-concept/overview">系列目录</a> · <a href="/life/english/new-concept/book-4/contents">本册目录</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元 5</a></p><h2 id="学习目标与内容导读" tabindex="-1">学习目标与内容导读 <a class="header-anchor" href="#学习目标与内容导读" aria-label="Permalink to &quot;学习目标与内容导读&quot;">​</a></h2><p>围绕公共支出阅读论证，区分预算总量、占比、变化幅度与价值判断。讨论虚构数字时要明确比较基数，避免“增加十个百分点”和“增加百分之十”混用。重点练习倍数和比例表达，使英语句子与简单计算对应，而不是用模糊形容词代替数据。</p><p>本课以主题阅读带动语言分析，学习重点如下。</p><h2 id="单词与搭配" tabindex="-1">单词与搭配 <a class="header-anchor" href="#单词与搭配" aria-label="Permalink to &quot;单词与搭配&quot;">​</a></h2><table tabindex="0"><thead><tr><th>单词</th><th>音标</th><th>词性</th><th>本页义项</th><th>搭配</th></tr></thead><tbody><tr><td>budget</td><td>/ˈbʌdʒɪt/</td><td>n.</td><td>预算</td><td>a public budget</td></tr><tr><td>expenditure</td><td>/ɪkˈspendɪtʃə/</td><td>n.</td><td>支出</td><td>annual expenditure</td></tr><tr><td>revenue</td><td>/ˈrevənjuː/</td><td>n.</td><td>收入</td><td>tax revenue</td></tr><tr><td>proportion</td><td>/prəˈpɔːʃən/</td><td>n.</td><td>比例</td><td>a small proportion</td></tr></tbody></table><h2 id="短语与句型" tabindex="-1">短语与句型 <a class="header-anchor" href="#短语与句型" aria-label="Permalink to &quot;短语与句型&quot;">​</a></h2><ul><li>account for — 占总量的某部分</li><li>increase by — 增加了某幅度</li></ul><h2 id="语法讲解-倍数比较与百分比基数" tabindex="-1">语法讲解：倍数比较与百分比基数 <a class="header-anchor" href="#语法讲解-倍数比较与百分比基数" aria-label="Permalink to &quot;语法讲解：倍数比较与百分比基数&quot;">​</a></h2><p>twice as much as 比较不可数数量，twice as many as 比较可数名词；three times the cost of… 也可表达倍数。increase by 20% 表增加幅度，increase to 20% 表达到的水平，两者不能互换。占比从 20% 到 30% 是增加 10 个百分点，相对原占比增加 50%。使用百分比必须给基数或可恢复的语境，否则读者可能把预算份额与绝对金额混淆。</p><h2 id="原创例句与结构分析" tabindex="-1">原创例句与结构分析 <a class="header-anchor" href="#原创例句与结构分析" aria-label="Permalink to &quot;原创例句与结构分析&quot;">​</a></h2><blockquote><p>In the fictional budget, maintenance costs rose from 100 units to 120 units, an increase of 20%.</p></blockquote><p>在虚构预算中，维护费从100单位升至120单位，增幅为20%。</p><p>from…to… 给起点终点；an increase of 20% 为同位补充，基数是原来的100。</p><h2 id="易错辨析" tabindex="-1">易错辨析 <a class="header-anchor" href="#易错辨析" aria-label="Permalink to &quot;易错辨析&quot;">​</a></h2><p>rose by 120 units 不等于 rose to 120 units；本例只增加20单位。</p><h2 id="听说训练" tabindex="-1">听说训练 <a class="header-anchor" href="#听说训练" aria-label="Permalink to &quot;听说训练&quot;">​</a></h2><p>朗读 20 percent 与 20 percentage points 作对比；再读 from 100 to 120，检查起点终点没有互换。</p><h2 id="读写训练" tabindex="-1">读写训练 <a class="header-anchor" href="#读写训练" aria-label="Permalink to &quot;读写训练&quot;">​</a></h2><h3 id="阅读材料-本站原创" tabindex="-1">阅读材料（本站原创） <a class="header-anchor" href="#阅读材料-本站原创" aria-label="Permalink to &quot;阅读材料（本站原创）&quot;">​</a></h3><p>The repair budget rose from 200 units to 250 units. This is an increase of 25%. We still need to know whether the higher amount covers more work or higher prices.</p><h3 id="表达任务" tabindex="-1">表达任务 <a class="header-anchor" href="#表达任务" aria-label="Permalink to &quot;表达任务&quot;">​</a></h3><p>用三句解释一个虚构预算变化：起止金额、计算增幅、仍需了解的信息。</p><details class="details custom-block"><summary>写作提示与点评</summary><p>数字可直接核算，最后区分数量增长和价格增长，不据金额变化直接判断效率。</p></details><h2 id="课后自测" tabindex="-1">课后自测 <a class="header-anchor" href="#课后自测" aria-label="Permalink to &quot;课后自测&quot;">​</a></h2><h3 id="练习-1" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1" aria-label="Permalink to &quot;练习 1&quot;">​</a></h3><p>100增到120，相对增幅是多少？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 20%。</p><p><strong>解析：</strong> (120−100)/100=20%。</p></details><h3 id="练习-2" tabindex="-1">练习 2 <a class="header-anchor" href="#练习-2" aria-label="Permalink to &quot;练习 2&quot;">​</a></h3><p>份额由20%到30%，增加多少个百分点？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 10个百分点。</p><p><strong>解析：</strong> 30%−20%=10个百分点。</p></details><h3 id="练习-3" tabindex="-1">练习 3 <a class="header-anchor" href="#练习-3" aria-label="Permalink to &quot;练习 3&quot;">​</a></h3><p>填空：This service costs twice as ___ as the other one.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> much</p><p><strong>解析：</strong> cost 的金额数量使用 much。</p></details><h2 id="复习导航" tabindex="-1">复习导航 <a class="header-anchor" href="#复习导航" aria-label="Permalink to &quot;复习导航&quot;">​</a></h2><p>本课重点：倍数比较与百分比基数。复习时先遮住答案重做自测，再将示范中的人物、时间或条件改为自己的情境；解释改动后哪些词需要变化。</p><p><a href="/life/english/new-concept/book-4/unit-05/grammar">单元语法</a> · <a href="/life/english/new-concept/book-4/unit-05/vocabulary">单元单词</a> · <a href="/life/english/new-concept/book-4/unit-05/review">单元自测</a></p><p><a href="/life/english/new-concept/book-4/unit-05/lesson-035">上一课</a> · <a href="/life/english/new-concept/book-4/unit-05/overview">单元目录</a> · <a href="/life/english/new-concept/book-4/unit-05/lesson-037">下一课</a></p><hr><p>本站原创学习伴读：保留经典版课号和课名，讲解、例句与练习独立编写。重点词汇用于本页学习，不等同于教材全部生词表；教材课文、完整译文、原题与录音请配合自己的正版教材使用。</p>',41)])])}const b=t(i,[["render",s]]);export{u as __pageData,b as default};
